/**
 * Writes src/transport/modp.ts: the 2048- and 4096-bit MODP groups of
 * RFC 3526 (groups 14 and 16), as OpenSSL carries them, which is where
 * Node's crypto.getDiffieHellman reads them from. test/transport/dh.test.ts
 * checks the file against the same source.
 *
 *   pnpm tsx scripts/modp-groups.ts
 */

import { getDiffieHellman } from 'node:crypto';
import { writeFileSync } from 'node:fs';

const groups = { MODP_2048: 'modp14', MODP_4096: 'modp16' } as const;
const lines = [
  '/**',
  ' * RFC 3526 MODP groups 14 and 16, generator 2. Generated by',
  ' * scripts/modp-groups.ts; do not edit.',
  ' */',
  '',
];
for (const [name, id] of Object.entries(groups)) {
  const hex = getDiffieHellman(id).getPrime('hex').toUpperCase();
  const chunks = hex.match(/.{1,96}/g)!;
  lines.push(
    `export const ${name} =`,
    chunks.map((chunk) => `  '${chunk}'`).join(' +\n') + ';',
    '',
  );
}
writeFileSync(new URL('../src/transport/modp.ts', import.meta.url), lines.join('\n'));
console.log('wrote', Object.keys(groups).join(', '));
